// SplitPal AI — explanation layer.
//
// This layer ONLY narrates numbers already computed by lib/split.ts. It never
// calculates, rounds, or alters an amount. In this build the narration is
// generated by deterministic templates (the "AI explanation" slot in the
// product design): if an LLM API key is configured the same structured facts
// can be sent to a model for richer wording, but the amounts shown are always
// copied verbatim from the split result.

import type { PersonShare } from "./split";

const fmt = (n: number) => n.toLocaleString("en-US");

export function explainShare(share: PersonShare): string {
  const items =
    share.itemNames.length > 0 ? share.itemNames.join(", ") : "no individual items";
  return (
    `${share.person}'s share is ₩${fmt(share.total)}: ` +
    `₩${fmt(share.itemSubtotal)} for ${items}, ` +
    `plus ₩${fmt(share.taxShare)} of the tax and ₩${fmt(share.tipShare)} of the tip, ` +
    `allocated in proportion to their items.`
  );
}

export function reminderDraft(share: PersonShare, payHint: string): string {
  return (
    `Hi ${share.person}! Here's your share from our group expense — ${explainShare(share)} ` +
    `You can settle it here: ${payHint} (PayPal Sandbox — no real money moves in the demo). Thanks!`
  );
}
